func TestAddSkillCommaFilter(t *testing.T) {
    fixture := makeAddFixture(t, map[string]string{
        "skills/alpha": addSkillMD("alpha", "Use when testing alpha."),
        "skills/beta":  addSkillMD("beta", "Use when testing beta."),
    })
    root := t.TempDir()

    // comma-separated installs both skills
    stdout, _, code := runCLI(t, "--root", root, "add", fixture, "--skill", "alpha,beta", "--text")
    if code != 0 {
        t.Fatal("expected success for comma-separated --skill filter")
    }
    if !strings.Contains(stdout, "alpha") {
        t.Errorf("expected 'alpha' in output, got: %s", stdout)
    }
    if !strings.Contains(stdout, "beta") {
        t.Errorf("expected 'beta' in output, got: %s", stdout)
    }
}

func TestAddSkillCommaFilterPartialMiss(t *testing.T) {
    fixture := makeAddFixture(t, map[string]string{
        "skills/alpha": addSkillMD("alpha", "Use when testing alpha."),
    })
    root := t.TempDir()

    _, stderr, code := runCLI(t, "--root", root, "add", fixture, "--skill", "alpha,missing")
    if code == 0 {
        t.Fatal("expected error when one comma-separated skill is not found")
    }
    if !strings.Contains(stderr, "missing") {
        t.Fatalf("expected not-found name 'missing' in error, got: %s", stderr)
    }
    if !strings.Contains(stderr, "alpha") {
        t.Fatalf("expected available skill 'alpha' in error, got: %s", stderr)
    }
    if !strings.Contains(stderr, "--skill") {
        t.Fatalf("expected '--skill' hint in error, got: %s", stderr)
    }
}

