def test_insert_pk_ignore_after_cross_table_inserts(fresh_db):
    user = {"id": "abc", "name": "david"}
    fresh_db["users"].insert(user, pk="id")
    fresh_db["comments"].insert_all(
        [{"id": "def", "text": "ok"}, {"id": "ghi", "text": "great"}],
    )
    # Must not raise IndexError (issue #554)
    fresh_db["users"].insert(user, ignore=True, pk="id")
    assert list(fresh_db["users"].rows) == [user]
